  'vec.title': "Vektorspalte für {table}",
  'vec.intro': "Fügt eine Embedding-Spalte vector(n) hinzu (n: die Dimensionen des Vektoranbieters), einen HNSW-Index für die Distanz und einen Trigger, der eine Zeile neu einbettet, wenn sich ihre Quellspalten ändern. Eine Suchkonfiguration vom Typ vector oder hybrid oder das Retrieve-Werkzeug eines KI-Agenten findet Zeilen dann nach Bedeutung. Die vorhandenen Zeilen werden sofort für ihre Embeddings eingereiht.",
  'vec.existing': "Vektorspalten jetzt",
  'vec.provider': "Vektoranbieter",
  'vec.provider_help': "Gemeinsame Komponenten › Vektoranbieter der Anwendungen dieses Arbeitsbereichs. Suchen Sie mit demselben Anbieter.",
  'vec.keep': "Aktuell halten",
  'vec.keep_help': "Ein Funktionsanbieter kann das Embedding sofort im Trigger setzen. Einen KI-Dienst ruft der Server auf: Der Trigger reiht die Zeile ein, und der Server bettet eingereihte Zeilen stapelweise ein, innerhalb der Anfragen pro Minute des Anbieters und der täglichen KI-Limits der Anwendung.",
  'vec.mode_set': "vom Trigger gesetzt, sofort",
  'vec.mode_queue': "für den Server eingereiht",
  'vec.sources': "Quellspalten",
