  'qs.syntax': 'Syntax',
  'qs.syntax.tables': 'Ein Tabellenname in einer eigenen Zeile, darunter eingerückt die Spalten. Eine unter einer anderen Tabelle eingerückte Tabelle ist eine Kindtabelle: Sie erhält `<parent>_id`, das auf die Elterntabelle verweist.',
  'qs.syntax.types': 'Spaltentypen aus dem Namen (`*_id` bigint, `*_at` timestamptz, `*_date`/`*_on` date, `is_*` boolean, `price`/`amount` numeric, sonst text) oder dahinter geschrieben: `vc200`, `num`, `num(10,2)`, `int`, `date`, `ts`, `tstz`, `clob`, `blob`, `json`, `bool`, `uuid`.',
  'qs.syntax.directives': 'Spaltendirektiven: `/nn`, `/pk`, `/unique`, `/idx`, `/fk table`, `/check a, b`, `/between 1 and 10`, `/default value`, `/lower`, `/upper`; `[a comment]`. Tabellendirektive: `/auditcols`.',
