  'rm.chk.no_role': 'Die Anwendung hat keine Datenbankrolle: Handler laufen als Laufzeitrolle von pgkiln. Geben Sie ihr eine eigene Rolle (Anwendung › Einstellungen), damit Berechtigungen und Row Level Security ihre eigenen sind.',
