  'rm.response_as': '{request} als {as}',
  'rm.try_intro': 'Sendet die Anfrage an den echten Endpunkt: Ein PUT, POST oder DELETE ändert Daten. {as} ein Konto stellt ein kurzlebiges Token dafür aus, wie es App › REST API tut; ohne sehen Sie, was ein Aufrufer ohne Token erhält.',
  'rm.intro': 'Module der RESTful Services: Ein Modul ist ein Basispfad einer Anwendung, seine Vorlagen sind URIs mit `:parameters`, und jede Vorlage hat Handler pro Methode mit ihrer Quelle: einer Sammlungsabfrage, einer einzelnen Zeile, SQL, einem PL/pgSQL-Block oder einer Medienressource. Handler laufen als Datenbankrolle der Anwendung mit dem Aufrufer als `meta.app_user()`, sodass deren Berechtigungen und Row Level Security gelten; Parameter werden gebunden, nie in das SQL eingefügt. Jedes Modul hat ein OpenAPI-Dokument. Module gehören zu ihrer Anwendung: Sie reisen mit deren Export (auch unter Gemeinsame Komponenten › RESTful Services).',
  'rm.source_help': 'Bindungen, in Großbuchstaben: Pfadparameter ({params}), Query-Parameter und Felder des JSON-Body; `:BODY` ist der ganze Body; `:APP_USER` ist der Aufrufer. Werte werden gebunden, nie in das SQL eingefügt. PL/pgSQL: ein Block (`declare … begin … end` oder Anweisungen), der mit `perform meta.rest_reply(jsonb_build_object(…), 201)` antwortet. Medien: eine Abfrage, die `content_type`, `content` und optional `filename` liefert.',
  'rm.params_help': 'Einer pro Zeile: `name query|body [{types}] [required] [description]`. Sie kommen in das OpenAPI-Dokument und das Formular „Ausprobieren“; fehlt ein erforderlicher, lautet die Antwort 400.',
  'rm.e.params_line': 'Parameter, Zeile {n}: Schreiben Sie "name query" oder "name body", dann optional einen Typ ({types}), "required" und eine Beschreibung.',
